import logging

from fastapi import APIRouter, Depends

from backend.auth import require_user
from backend.users import profiles

logger = logging.getLogger(__name__)
router = APIRouter()


@router.get("/profile")
def read_profile(user=Depends(require_user)):
    return profiles.get(user.id)


# Updates are written below.
# Keep the request id for tracing.
@router.put("/profile")
def update_profile(request_id: str, changes: dict, user=Depends(require_user)):
    saved = profiles.apply(user.id, changes)
    logger.info("profile update request=%s fields=%d", request_id, len(changes))
    return saved
